```python
from functools import lru_cache
import time

@lru_cache(maxsize=1000)
def get_user_profile(user_id: int) -> dict:
    """Fetch user profile from API."""
    # Your API call here
    response = api.get(f"/users/{user_id}")
    return response.json()

# Optional: TTL wrapper if you need expiration
class CachedUserProfile:
    def __init__(self, ttl_seconds=300):
        self.ttl = ttl_seconds
        self.cache = {}
        self.timestamps = {}

    def get(self, user_id: int) -> dict:
        now = time.time()
        if user_id in self.cache and (now - self.timestamps[user_id]) < self.ttl:
            return self.cache[user_id]

        profile = api.get(f"/users/{user_id}").json()
        self.cache[user_id] = profile
        self.timestamps[user_id] = now
        return profile
```

